def summarize(x,depth=0,seen=None):
 if seen is None: seen=collections.Counter()
 t=type(x).__name__; seen[t]+=1
 if depth>5: return {'type':t,'omitted':'depth'}
 if isinstance(x,dict):
  out=[]
  for k,v in x.items():
   ks=repr(k)[:120]
   out.append({'key_repr':ks,'value':summarize(v,depth+1,seen)})
